package com.clavis.reader;
import android.app.*;import android.app.job.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.RecyclerView;import androidx.swiperefreshlayout.widget.SwipeRefreshLayout;import java.util.*;import org.json.*;
final class FeedExperienceChecks {
 static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static boolean pull(View view){if(view instanceof SwipeRefreshLayout)return true;if(view instanceof android.view.ViewGroup)for(int n=0;n<((android.view.ViewGroup)view).getChildCount();n++)if(pull(((android.view.ViewGroup)view).getChildAt(n)))return true;return false;}
 static String run(Instrumentation test)throws Exception{Context c=test.getTargetContext();JSONArray entries=FeedCatalog.catalog(c);HashSet<String> unique=new HashSet<>(),topics=new HashSet<>();int news=0,journals=0,nonMedical=0;for(int n=0;n<entries.length();n++){JSONObject entry=entries.getJSONObject(n);if(entry.getString("kind").equals("Podcasts"))continue;check(unique.add(entry.getString("kind")+entry.getString("url")),"Unique curated source");JSONArray tags=entry.getJSONArray("tags");check(tags.length()>0,"Curated sources have topics");for(int t=0;t<tags.length();t++)topics.add(tags.getString(t));if(entry.getString("kind").equals("News")){news++;check(entry.getString("contentMode").equals("full-feed"),"News catalog uses full-content feeds");}else{journals++;if(!tags.toString().contains("Medical"))nonMedical++;check(entry.getString("contentMode").equals("open-access"),"Journal catalog is open access");}}check(news==50&&journals==50,"Fifty News and fifty journal sources");check(nonMedical>=25&&topics.size()>=12,"Journal catalog covers subjects beyond medicine");
  android.content.SharedPreferences prefs=FeedTopics.prefs(c),refresh=c.getSharedPreferences("feed_refresh",0);Set<String> oldNews=FeedTopics.selected(c,"News"),oldJournals=FeedTopics.selected(c,"Journals");boolean latest=prefs.getBoolean("latest_News",false);long newsAttempt=refresh.getLong("attempt_News",0),journalAttempt=refresh.getLong("attempt_Journals",0);MainActivity activity=null;
  try{prefs.edit().putStringSet("News",new HashSet<>(Collections.singletonList("Medical"))).apply();FeedStore.Feed general=new FeedStore.Feed();general.kind="News";FeedStore.Item health=new FeedStore.Item(),space=new FeedStore.Item();health.title="New clinical medicine research improves patient care";space.title="A distant galaxy and its planets";check(FeedTopics.item(c,general,health),"Medical filter finds relevant stories in broad sources");check(!FeedTopics.item(c,general,space),"Medical filter excludes unrelated stories");prefs.edit().remove("News").putBoolean("latest_News",true).apply();FeedStore.Item older=new FeedStore.Item(),newer=new FeedStore.Item();older.id="older-check";older.date="2025-01-01T00:00:00Z";newer.id="newer-check";newer.date="2026-10-29T00:00:00Z";general.items.add(older);general.items.add(newer);check(FeedHighlights.ranked(c,"News",Collections.singletonList(general)).get(0).item==newer,"Refresh latest mode puts newest story first");
   final String paragraph="हिन्दी समाचार पढ़ते समय शब्दों की मात्राएँ पूरी दिखनी चाहिए। स्वास्थ्य, दृष्टि, क्षितिज और प्रौद्योगिकी से जुड़ी जानकारी यहाँ स्पष्ट रूप से प्रस्तुत की गई है।";String text=(paragraph+"\n\n").repeat(45);test.runOnMainSync(()->{for(int size:new int[]{18,26}){TextView sample=new TextView(c);sample.setTextSize(size);sample.setTypeface(Typeface.SERIF);HindiTypography.apply(sample,text);check(sample.getTypeface()==HindiTypography.face(c,false),"Supplied Noto Devanagari font renders Hindi");check(sample.getIncludeFontPadding(),"Hindi glyph padding enabled");int width=(int)(320*c.getResources().getDisplayMetrics().density),height=(int)(350*c.getResources().getDisplayMetrics().density),extra=(int)(3*c.getResources().getDisplayMetrics().density),gap=(int)(16*c.getResources().getDisplayMetrics().density);ArrayList<StoryPages.Page> pages=StoryPages.paginate(text,sample.getPaint(),width,height,extra,1.16f,gap);StringBuilder rebuilt=new StringBuilder();for(StoryPages.Page page:pages){rebuilt.append(page.text);check(StoryPages.layout(StoryPages.spaced(page.text,gap,extra,1.16f),sample.getPaint(),width,extra,1.16f).getHeight()<=height,"Hindi pages fit with vowel-mark padding at larger sizes");}check(rebuilt.toString().equals(text),"Hindi pagination preserves every character");}});
   refresh.edit().putLong("attempt_News",System.currentTimeMillis()).putLong("attempt_Journals",System.currentTimeMillis()).commit();activity=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MainActivity a=activity;test.runOnMainSync(()->FeedRefresh.forget(a));FeedStore.Feed fixture=new FeedStore.Feed();fixture.kind="News";fixture.title="हिन्दी समाचार";fixture.url="https://example.invalid/hindi-font-check";fixture.fullText=true;FeedStore.Item story=new FeedStore.Item();story.id="hindi-font-check";story.title="स्वास्थ्य और विज्ञान की नई जानकारी: हिन्दी में स्पष्ट समाचार";story.description="<p>"+String.join("</p><p>",Collections.nCopies(15,paragraph))+"</p>";story.date="2026-10-29T00:00:00Z";fixture.items.add(story);test.runOnMainSync(()->FeedPosts.show(a,fixture));test.waitForIdleSync();SystemClock.sleep(600);final FeedPosts.PostHolder[] card={null};test.runOnMainSync(()->{RecyclerView posts=FeedPostChecks.posts(a.mainFrame);card[0]=(FeedPosts.PostHolder)posts.findViewHolderForAdapterPosition(0);check(card[0]!=null,"Hindi article card renders");check(pull(a.mainFrame),"News reader has pull-to-refresh");check(card[0].pager.getHeight()<FeedPosts.viewportHeight(a,true),"Hindi title-only cover is compact");card[0].pager.setCurrentItem(1,true);});SystemClock.sleep(600);test.waitForIdleSync();test.runOnMainSync(()->{FeedPosts.PostHolder h=card[0];check(h.pager.getHeight()==FeedPosts.viewportHeight(a,false),"Hindi story expands to full reader height");RecyclerView inner=(RecyclerView)h.pager.getChildAt(0);FeedPosts.Slide slide=(FeedPosts.Slide)inner.findViewHolderForAdapterPosition(1);check(slide!=null&&slide.text.getTypeface()==HindiTypography.face(a,false),"Visible Hindi story uses supplied font");check(slide.text.getLayout().getHeight()<=slide.text.getHeight()-slide.text.getPaddingTop()-slide.text.getPaddingBottom(),"Visible Hindi text is not clipped");JobInfo job=a.getSystemService(JobScheduler.class).getPendingJob(7131);check(job!=null&&job.isPeriodic(),"Background RSS refresh is scheduled");});FeedPostChecks.snapshot(test,c,"hindi-story");return checks+" catalog, topics, Hindi, compact-card and refresh checks passed\n";
  }finally{MainActivity close=activity;if(close!=null)test.runOnMainSync(close::finish);prefs.edit().putStringSet("News",oldNews).putStringSet("Journals",oldJournals).putBoolean("latest_News",latest).commit();refresh.edit().putLong("attempt_News",newsAttempt).putLong("attempt_Journals",journalAttempt).commit();}
 }
}
